function StatusBadge({ status }) {
  const map = {
    verified: { label: "Verified", fg: C.success, bg: C.successBg, bd: C.successBorder, Icon: CheckCircle2 },
    review: { label: "Requires review", fg: C.warning, bg: C.warningBg, bd: C.warningBorder, Icon: AlertTriangle },
    failed: { label: "Failed", fg: C.danger, bg: C.dangerBg, bd: C.dangerBorder, Icon: XCircle },
    incomplete: { label: "Incomplete", fg: C.textSecondary, bg: "rgba(120,125,145,0.12)", bd: "rgba(120,125,145,0.22)", Icon: AlertTriangle },
  };
  const s = map[status];
  const Icon = s.Icon;
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px", borderRadius: 8, background: s.bg, border: `1px solid ${s.bd}`, color: s.fg, fontSize: 12.5, fontWeight: 600, fontFamily: sans, whiteSpace: "nowrap" }}>
      <Icon size={13} strokeWidth={2.4} />
      {s.label}
    </span>
  );
}

function SeverityTag({ level }) {
  const map = {
    high: { label: "High", fg: C.danger, bg: C.dangerBg, bd: C.dangerBorder },
    medium: { label: "Medium", fg: C.warning, bg: C.warningBg, bd: C.warningBorder },
    low: { label: "Low", fg: C.textSecondary, bg: "rgba(120,125,145,0.12)", bd: "rgba(120,125,145,0.22)" },
  };
  const s = map[level];
  return (
    <span style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: 0.3, color: s.fg, background: s.bg, border: `1px solid ${s.bd}`, borderRadius: 6, padding: "3px 8px", fontFamily: sans }}>
      {s.label.toUpperCase()}
    </span>
  );
}

function MetricCard({ label, value, sub, tone, icon: Icon }) {
  const toneColor = tone === "success" ? C.success : tone === "warning" ? C.warning : tone === "danger" ? C.danger : C.text;
  return (
    <div style={glass({ padding: "18px 20px", flex: 1, minWidth: 0 })}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
        {Icon && (
          <div style={{ width: 34, height: 34, borderRadius: "50%", background: "rgba(255,255,255,0.75)", border: `1px solid ${C.glassBorder}`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <Icon size={16} color={C.primary} />
          </div>
        )}
        <div style={{ fontSize: 13, color: C.textSecondary, fontFamily: sans }}>{label}</div>
      </div>
      <div style={{ fontSize: 26, fontWeight: 800, color: toneColor, fontFamily: sans, lineHeight: 1.1 }}>{value}</div>
      {sub && <div style={{ fontSize: 12.5, color: C.textTertiary, marginTop: 6, fontFamily: sans }}>{sub}</div>}
    </div>
  );
}

function PageHeader({ eyebrow, title, description, action }) {
  return (
    <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", marginBottom: 26, gap: 16 }}>
      <div>
        {eyebrow && <div style={{ fontSize: 13, color: C.accent, fontFamily: sans, fontWeight: 700, marginBottom: 6 }}>{eyebrow}</div>}
        <h1 style={{ fontSize: 30, fontWeight: 800, color: C.text, fontFamily: sans, margin: 0 }}>{title}</h1>
        {description && <p style={{ fontSize: 14.5, color: C.textSecondary, fontFamily: sans, margin: "8px 0 0", maxWidth: 620 }}>{description}</p>}
      </div>
      {action}
    </div>
  );
}

function PrimaryButton({ children, onClick, icon: Icon, style }) {
  return (
    <button onClick={onClick} style={{ display: "inline-flex", alignItems: "center", gap: 8, background: `linear-gradient(135deg, ${C.primary}, ${C.accent})`, color: "#fff", border: "none", borderRadius: 12, padding: "11px 18px", fontSize: 14, fontWeight: 700, fontFamily: sans, cursor: "pointer", boxShadow: "0 8px 20px rgba(91,99,232,0.35)", ...style }}>
      {children}
      {Icon && <Icon size={15} />}
    </button>
  );
}

function SecondaryButton({ children, onClick, icon: Icon, style }) {
  return (
    <button onClick={onClick} style={{ display: "inline-flex", alignItems: "center", gap: 8, background: "rgba(255,255,255,0.6)", backdropFilter: "blur(10px)", color: C.text, border: `1px solid ${C.glassBorder}`, borderRadius: 10, padding: "10px 16px", fontSize: 13.5, fontWeight: 600, fontFamily: sans, cursor: "pointer", ...style }}>
      {Icon && <Icon size={14} />}
      {children}
    </button>
  );
}

function RiskGauge({ score }) {
  const color = score < 30 ? C.success : score < 60 ? C.warning : C.danger;
  const r = 46;
  const cc = 2 * Math.PI * r;
  const offset = cc - (score / 100) * cc;
  return (
    <div style={{ position: "relative", width: 116, height: 116 }}>
      <svg width="116" height="116" viewBox="0 0 116 116">
        <circle cx="58" cy="58" r={r} fill="none" stroke="rgba(120,125,160,0.18)" strokeWidth="10" />
        <circle cx="58" cy="58" r={r} fill="none" stroke={color} strokeWidth="10" strokeDasharray={cc} strokeDashoffset={offset} strokeLinecap="round" transform="rotate(-90 58 58)" />
      </svg>
      <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
        <div style={{ fontSize: 26, fontWeight: 800, color: C.text, fontFamily: sans, lineHeight: 1 }}>{score}</div>
        <div style={{ fontSize: 11, color: C.textTertiary, fontFamily: sans, marginTop: 2 }}>risk / 100</div>
      </div>
    </div>
  );
}

