function TopBar({ page, setPage }) {
  const activeGroup = (key) => {
    if (key === "bundles" && (page === "bundle-detail" || page === "documents" || page === "document-detail")) return true;
    return page === key;
  };
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 22, padding: "6px 4px", marginBottom: 30 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 9, flexShrink: 0 }}>
        <div style={{ width: 28, height: 28, borderRadius: 9, background: `linear-gradient(135deg, ${C.primary}, ${C.accent})`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, boxShadow: "0 6px 14px rgba(91,99,232,0.3)" }}>
          <ShieldCheck size={14} color="#fff" strokeWidth={2.2} />
        </div>
        <div style={{ fontSize: 14, fontWeight: 800, color: C.text, fontFamily: sans, lineHeight: 1.2, whiteSpace: "nowrap" }}>Audit Evidence</div>
      </div>

      <nav style={{ display: "flex", alignItems: "center", justifyContent: "space-evenly", flex: 1, overflowX: "auto" }}>
        {NAV_ITEMS.map(({ key, label }) => {
          const active = activeGroup(key);
          return (
            <button
              key={key}
              onClick={() => setPage(key)}
              style={{
                border: "none",
                background: "none",
                padding: "4px 0",
                color: active ? C.primary : C.textSecondary,
                fontFamily: sans,
                fontSize: 13.5,
                fontWeight: active ? 700 : 500,
                cursor: "pointer",
                whiteSpace: "nowrap",
                borderBottom: active ? `2px solid ${C.accent}` : "2px solid transparent",
              }}
            >
              {label}
            </button>
          );
        })}
      </nav>

      <div style={{ width: 28, height: 28, borderRadius: "50%", background: `linear-gradient(135deg, ${C.primary}, ${C.accent})`, color: "#fff", fontFamily: sans, fontSize: 12, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>AK</div>
    </div>
  );
}

