const SLOT_DEFS = [
  { key: "po", label: "Purchase order", hint: "PO PDF — po number, vendor, subtotal" },
  { key: "invoice", label: "Invoice", hint: "Vendor invoice PDF — tax breakdown, totals" },
  { key: "grn", label: "Goods received note", hint: "GRN PDF — received quantities, pre-tax amount" },
  { key: "bank", label: "Bank statement", hint: "Bank narration or payment statement PDF" },
];

function UploadSlot({ def, state, onAttach, onRemove }) {
  const attached = state.status === "success";
  return (
    <div style={{ ...glassSoft({ padding: "18px 16px", display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", gap: 4, position: "relative" }), background: attached ? "rgba(20,150,110,0.1)" : "rgba(255,255,255,0.4)", border: `1px solid ${attached ? C.successBorder : C.glassBorderSoft}` }}>
      {attached && (
        <button onClick={onRemove} style={{ position: "absolute", top: 10, right: 10, background: "none", border: "none", color: C.textTertiary, cursor: "pointer", padding: 2 }}>
          <X size={13} />
        </button>
      )}
      <div style={{ width: 38, height: 38, borderRadius: 10, background: "rgba(255,255,255,0.8)", border: `1px solid ${attached ? C.successBorder : C.glassBorder}`, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 6 }}>
        {attached ? <CheckCircle2 size={18} color={C.success} /> : <FileText size={17} color={C.accent} />}
      </div>
      <div style={{ fontSize: 14, fontWeight: 700, color: C.text, fontFamily: sans }}>{def.label}</div>
      <div style={{ fontSize: 12, color: C.textTertiary, fontFamily: sans, lineHeight: 1.4, minHeight: 32 }}>{def.hint}</div>
      {attached ? (
        <div style={{ marginTop: 4 }}>
          <div style={{ fontSize: 12.5, fontFamily: mono, color: C.success, fontWeight: 700 }}>{state.filename}</div>
          <div style={{ fontSize: 11.5, color: C.textTertiary, fontFamily: sans, marginTop: 2 }}>Extracted successfully</div>
        </div>
      ) : (
        <button onClick={onAttach} style={{ marginTop: 6, fontSize: 12.5, fontWeight: 700, color: C.accent, background: "none", border: "none", cursor: "pointer", fontFamily: sans }}>Attach PDF</button>
      )}
    </div>
  );
}

function NewUploadPage() {
  const [ref, setRef] = useState("TXN-2026-707");
  const [slots, setSlots] = useState({
    po: { status: "success", filename: "purchase_order_100007.pdf" },
    invoice: { status: "success", filename: "invoice_200007.pdf" },
    grn: { status: "empty" },
    bank: { status: "empty" },
  });

  const attach = (key) => {
    const names = { grn: "grn_0007.pdf", bank: "bank_statement_april.pdf" };
    setSlots((s) => ({ ...s, [key]: { status: "success", filename: names[key] } }));
  };
  const remove = (key) => setSlots((s) => ({ ...s, [key]: { status: "empty" } }));
  const attachedCount = Object.values(slots).filter((s) => s.status === "success").length;
  const ready = attachedCount === 4;

  return (
    <div>
      <PageHeader eyebrow="EVIDENCE INTAKE" title="New upload" description="Attach the four documents required for a deterministic 4-way audit match." />
      <div style={{ ...glass({ padding: 28 }), maxWidth: 920 }}>
        <div style={{ marginBottom: 22 }}>
          <label style={{ fontSize: 13, fontWeight: 700, color: C.text, fontFamily: sans, display: "block", marginBottom: 8 }}>Transaction reference</label>
          <input value={ref} onChange={(e) => setRef(e.target.value)} style={{ width: "100%", maxWidth: 320, padding: "10px 14px", borderRadius: 10, border: `1px solid ${C.glassBorder}`, background: "rgba(255,255,255,0.6)", fontFamily: mono, fontSize: 14, color: C.text, outline: "none" }} />
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14, marginBottom: 24 }}>
          {SLOT_DEFS.map((def) => (
            <UploadSlot key={def.key} def={def} state={slots[def.key]} onAttach={() => attach(def.key)} onRemove={() => remove(def.key)} />
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", paddingTop: 18, borderTop: `1px solid ${C.glassBorderSoft}` }}>
          {ready ? (
            <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: C.success, fontFamily: sans, fontWeight: 700 }}><CheckCircle2 size={15} /> All four documents attached and extracted</div>
          ) : (
            <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: C.warning, fontFamily: sans, fontWeight: 700 }}><AlertTriangle size={15} /> {4 - attachedCount} document{4 - attachedCount > 1 ? "s" : ""} still needed</div>
          )}
          <PrimaryButton icon={ArrowRight} style={!ready ? { opacity: 0.45, cursor: "not-allowed" } : {}}>Create audit bundle</PrimaryButton>
        </div>
      </div>
    </div>
  );
}

