function MatchFlow() {
  const steps = ["Purchase order", "Invoice", "Goods received note", "Bank statement"];
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 0 }}>
      {steps.map((s, i) => (
        <React.Fragment key={s}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ width: 26, height: 26, borderRadius: "50%", background: C.successBg, border: `1px solid ${C.successBorder}`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><CheckCircle2 size={14} color={C.success} /></div>
            <span style={{ fontSize: 14, fontWeight: 700, color: C.text, fontFamily: sans }}>{s}</span>
          </div>
          {i < steps.length - 1 && <div style={{ width: 1, height: 22, background: C.glassBorderSoft, marginLeft: 13 }} />}
        </React.Fragment>
      ))}
      <div style={{ width: 1, height: 22, background: C.glassBorderSoft, marginLeft: 13 }} />
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ width: 26, height: 26, borderRadius: "50%", background: C.warningBg, border: `1px solid ${C.warningBorder}`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><AlertTriangle size={14} color={C.warning} /></div>
        <span style={{ fontSize: 14, fontWeight: 800, color: C.text, fontFamily: sans }}>Verification result — 3 discrepancies found</span>
      </div>
    </div>
  );
}

